(7701352, 1264259, 67258, '<td valign="top">Excellent composition, superb mono conversion.  the viewer really does get the sense that the great unknown lies just beyond.  Quite terrifying!</td>', 'Excellent composition, superb mono conversion.  the viewer really does get the sense that the great unknown lies just beyond.  Quite terrifying!', '2021-09-15 05:43:40.000000', NULL, 1),
